(()=>{'use strict';
const t={
en:['Image search','Choose a product image to find visually similar products. Your image stays in your browser.','Choose an image','Visually similar products','After selecting an image, results open in the Joyagoo Sheet Lab product list, ordered by approximate visual similarity.','← Back to products','Choose a JPG, PNG or WebP image up to 15 MB.'],
zh:['以图搜商品','选择商品图片，查找外观相似的商品。图片保留在您的浏览器中。','选择图片','外观相似的商品','选择图片后，将进入 Joyagoo 商品列表，按大致视觉相似度排列结果。','← 返回商品列表','请选择不超过 15 MB 的 JPG、PNG 或 WebP 图片。'],
de:['Bildersuche','Wähle ein Produktbild, um optisch ähnliche Produkte zu finden. Das Bild bleibt im Browser.','Bild auswählen','Optisch ähnliche Produkte','Nach der Auswahl öffnet sich die Joyagoo-Produktliste mit nach visueller Ähnlichkeit sortierten Ergebnissen.','← Zurück zu Produkten','Wähle ein JPG-, PNG- oder WebP-Bild bis 15 MB.'],
fr:['Recherche par image','Choisissez une image pour trouver des produits visuellement similaires. Elle reste dans votre navigateur.','Choisir une image','Produits visuellement similaires','Après sélection, la liste Joyagoo affiche les résultats par similarité visuelle approximative.','← Retour aux produits','Choisissez une image JPG, PNG ou WebP de 15 Mo maximum.'],
es:['Búsqueda por imagen','Elige una imagen para encontrar productos visualmente similares. La imagen permanece en tu navegador.','Elegir imagen','Productos visualmente similares','Tras elegir la imagen, la lista de Joyagoo muestra resultados ordenados por similitud visual aproximada.','← Volver a productos','Elige una imagen JPG, PNG o WebP de hasta 15 MB.'],
it:['Ricerca per immagine','Scegli un’immagine per trovare prodotti visivamente simili. L’immagine resta nel browser.','Scegli un’immagine','Prodotti visivamente simili','Dopo la selezione si apre l’elenco Joyagoo, ordinato per somiglianza visiva approssimativa.','← Torna ai prodotti','Scegli un’immagine JPG, PNG o WebP fino a 15 MB.'],
pt:['Pesquisa por imagem','Escolha uma imagem para encontrar produtos visualmente semelhantes. A imagem fica no navegador.','Escolher imagem','Produtos visualmente semelhantes','Após escolher, a lista Joyagoo abre com resultados ordenados por semelhança visual aproximada.','← Voltar aos produtos','Escolha uma imagem JPG, PNG ou WebP de até 15 MB.'],
nl:['Zoeken met afbeelding','Kies een productafbeelding om visueel vergelijkbare producten te vinden. De afbeelding blijft in je browser.','Kies een afbeelding','Visueel vergelijkbare producten','Na het kiezen opent de Joyagoo-productlijst, gesorteerd op geschatte visuele gelijkenis.','← Terug naar producten','Kies een JPG-, PNG- of WebP-afbeelding van maximaal 15 MB.'],
pl:['Wyszukiwanie obrazem','Wybierz zdjęcie produktu, aby znaleźć podobne wizualnie produkty. Zdjęcie pozostaje w przeglądarce.','Wybierz obraz','Produkty podobne wizualnie','Po wyborze otworzy się lista Joyagoo uporządkowana według przybliżonego podobieństwa wizualnego.','← Wróć do produktów','Wybierz obraz JPG, PNG lub WebP o rozmiarze do 15 MB.'],
sv:['Bildsökning','Välj en produktbild för att hitta visuellt liknande produkter. Bilden stannar i webbläsaren.','Välj en bild','Visuellt liknande produkter','Efter valet öppnas Joyagoos produktlista sorterad efter ungefärlig visuell likhet.','← Tillbaka till produkter','Välj en JPG-, PNG- eller WebP-bild på högst 15 MB.'],
fi:['Kuvahaku','Valitse tuotekuva löytääksesi samannäköisiä tuotteita. Kuva pysyy selaimessasi.','Valitse kuva','Samannäköiset tuotteet','Valinnan jälkeen avautuu Joyagoo-tuotelista, joka järjestetään arvioidun visuaalisen samankaltaisuuden mukaan.','← Takaisin tuotteisiin','Valitse enintään 15 Mt:n JPG-, PNG- tai WebP-kuva.'],
da:['Billedsøgning','Vælg et produktbillede for at finde visuelt lignende produkter. Billedet bliver i din browser.','Vælg et billede','Visuelt lignende produkter','Efter valget åbnes Joyagoos produktliste sorteret efter omtrentlig visuel lighed.','← Tilbage til produkter','Vælg et JPG-, PNG- eller WebP-billede på højst 15 MB.'],
nb:['Bildesøk','Velg et produktbilde for å finne visuelt lignende produkter. Bildet blir i nettleseren.','Velg et bilde','Visuelt lignende produkter','Etter valget åpnes Joyagoos produktliste sortert etter omtrentlig visuell likhet.','← Tilbake til produkter','Velg et JPG-, PNG- eller WebP-bilde på opptil 15 MB.'],
cs:['Vyhledávání podle obrázku','Vyberte obrázek produktu a najděte vizuálně podobné produkty. Obrázek zůstává v prohlížeči.','Vybrat obrázek','Vizuálně podobné produkty','Po výběru se otevře seznam Joyagoo seřazený podle přibližné vizuální podobnosti.','← Zpět na produkty','Vyberte obrázek JPG, PNG nebo WebP do 15 MB.'],
hu:['Keresés képpel','Válassz termékképet a hasonló termékek kereséséhez. A kép a böngésződben marad.','Kép kiválasztása','Vizuálisan hasonló termékek','A választás után megnyílik a Joyagoo terméklista, becsült vizuális hasonlóság szerint rendezve.','← Vissza a termékekhez','Válassz legfeljebb 15 MB-os JPG-, PNG- vagy WebP-képet.'],
ro:['Căutare după imagine','Alege o imagine de produs pentru a găsi produse asemănătoare vizual. Imaginea rămâne în browser.','Alege o imagine','Produse asemănătoare vizual','După selecție se deschide lista Joyagoo, ordonată după asemănarea vizuală aproximativă.','← Înapoi la produse','Alege o imagine JPG, PNG sau WebP de cel mult 15 MB.'],
el:['Αναζήτηση με εικόνα','Επιλέξτε εικόνα προϊόντος για να βρείτε οπτικά παρόμοια προϊόντα. Η εικόνα παραμένει στο πρόγραμμα περιήγησης.','Επιλογή εικόνας','Οπτικά παρόμοια προϊόντα','Μετά την επιλογή ανοίγει η λίστα Joyagoo, ταξινομημένη κατά προσέγγιση οπτικής ομοιότητας.','← Επιστροφή στα προϊόντα','Επιλέξτε εικόνα JPG, PNG ή WebP έως 15 MB.'],
tr:['Görselle arama','Görsel olarak benzer ürünleri bulmak için bir ürün görseli seçin. Görsel tarayıcınızda kalır.','Görsel seç','Görsel olarak benzer ürünler','Seçimden sonra Joyagoo ürün listesi yaklaşık görsel benzerliğe göre sıralanarak açılır.','← Ürünlere dön','En fazla 15 MB JPG, PNG veya WebP görseli seçin.'],
uk:['Пошук за зображенням','Виберіть зображення товару, щоб знайти візуально схожі товари. Зображення залишається в браузері.','Вибрати зображення','Візуально схожі товари','Після вибору відкриється список Joyagoo, упорядкований за приблизною візуальною схожістю.','← До товарів','Виберіть зображення JPG, PNG або WebP до 15 МБ.'],
ar:['البحث بالصورة','اختر صورة منتج للعثور على منتجات متشابهة بصرياً. تبقى الصورة في متصفحك.','اختر صورة','منتجات متشابهة بصرياً','بعد الاختيار تفتح قائمة منتجات Joyagoo مرتبة حسب التشابه البصري التقريبي.','العودة إلى المنتجات ←','اختر صورة JPG أو PNG أو WebP بحجم لا يتجاوز 15 ميغابايت.'],
ja:['画像検索','商品画像を選んで、見た目が似ている商品を探します。画像はブラウザ内に保持されます。','画像を選択','見た目が似ている商品','選択後、Joyagooの商品一覧に移動し、おおよその視覚的類似度順に表示します。','← 商品一覧へ戻る','15 MB以下のJPG、PNG、WebP画像を選んでください。'],
ko:['이미지 검색','상품 이미지를 선택해 시각적으로 비슷한 상품을 찾아보세요. 이미지는 브라우저에 남습니다.','이미지 선택','시각적으로 비슷한 상품','이미지를 선택하면 Joyagoo 상품 목록에서 대략적인 시각적 유사도 순으로 결과가 표시됩니다.','← 상품으로 돌아가기','15 MB 이하의 JPG, PNG 또는 WebP 이미지를 선택하세요.'],
ru:['Поиск по изображению','Выберите изображение товара, чтобы найти визуально похожие товары. Изображение остаётся в браузере.','Выбрать изображение','Визуально похожие товары','После выбора откроется список Joyagoo с сортировкой по приблизительному визуальному сходству.','← К товарам','Выберите изображение JPG, PNG или WebP размером до 15 МБ.'],
id:['Pencarian gambar','Pilih gambar produk untuk menemukan produk yang mirip secara visual. Gambar tetap di browser Anda.','Pilih gambar','Produk yang mirip secara visual','Setelah memilih gambar, daftar produk Joyagoo akan terbuka dan diurutkan berdasarkan perkiraan kemiripan visual.','← Kembali ke produk','Pilih gambar JPG, PNG, atau WebP hingga 15 MB.']};
const keys=['title','intro','choose','heading','details','back'],menu=document.querySelector('.language'),file=document.querySelector('#image-file'),err=document.querySelector('.image-page-error');let lang='en';function update(){lang=t[menu?.value]?menu.value:'en';keys.forEach((k,i)=>{document.querySelector('[data-copy="'+k+'"]').textContent=t[lang][i]});document.title=t[lang][0]+' | Joyagoo Sheet Lab'}menu?.addEventListener('change',update);update();
document.querySelector('.image-page-choose').addEventListener('click',()=>file.click());
file.addEventListener('change',()=>{const f=file.files?.[0];err.hidden=true;if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>15*1024*1024){err.textContent=t[lang][6];err.hidden=false;file.value='';return}const img=new Image(),url=URL.createObjectURL(f);img.onload=()=>{try{const c=document.createElement('canvas'),scale=Math.min(1,640/Math.max(img.naturalWidth,img.naturalHeight));c.width=Math.max(1,Math.round(img.naturalWidth*scale));c.height=Math.max(1,Math.round(img.naturalHeight*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);sessionStorage.setItem('joy-image-search',c.toDataURL('image/jpeg',.9));sessionStorage.setItem('joy-image-search-name',f.name.slice(0,255));URL.revokeObjectURL(url);location.href='/catalog/?imageSearch=1'}catch(e){URL.revokeObjectURL(url);err.textContent=t[lang][6];err.hidden=false}};img.onerror=()=>{URL.revokeObjectURL(url);err.textContent=t[lang][6];err.hidden=false};img.src=url});
document.querySelector('.menu')?.addEventListener('click',e=>{const nav=document.querySelector('#nav'),open=nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});})();
